def find_case(rows, case):
    for item in rows:
        if item["case"] == case:
            return item
    return None

def snapshot_for(diag, catalogue):
    refs = [p["ordinal"] for p in catalogue]
    return {"case": diag["case"], "ref": f"snapshot/{diag['case']}/{len(refs)}",
            "diag_ref": diag["ref"], "visible": refs}
